{"results": [{"id": "FAM:SF-APPA-054", "label": "Study family SF-APPA-054: PUTBACK suppression mechanism: fatigue vs value", "score": 0.313, "reached_via": ["FAM:SF-APPA-050 auto_related_family (record_link_extends) FAM:SF-APPA-054", "request matches RISK:EXPOSURE_SPARSITY (0.22); FAM:SF-APPA-054 auto_has_risk RISK:EXPOSURE_SPARSITY"], "attributes": {"observed_research_question": "PUTBACK suppression mechanism: fatigue vs value", "auto_outcome_status": "supported", "observed_hypothesis": "PUTBACK suppresses the next star possession via fatigue (stronger in H2 and Q4), while PUTBACK itself remains high-value.", "observed_result": "H1 delta -0.038 vs H2 -0.130 (22 stars, 3.4x). Q1 -0.009 vs Q4 -0.289 (11 stars; Q4 pooled n=34). PUTBACK H2 1.528 vs 1.217 (+0.311) n=8,614 vs 474,564. After opp PUTBACK offense 1.097 vs 1.210 (d=-0.113) n=15,898.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "Q4 PUTBACK is sparse (34 pooled poss at n>=30; Mitchell n=34 drives the Q4 cell) even though the H2 vs H1 and aftershock tests are larger.", "observed_verdict": "supported"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:insufficient_exposure"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:EXPOSURE_SPARSITY"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}, {"rel": "auto_related_family", "node": "FAM:SF-APPA-050"}]}, {"id": "FAM:SF-APPA-050", "label": "Study family SF-APPA-050: Superstar sequential suppression: opponent play before the star", "score": 0.288, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPA-050 (0.24)", "request matches VAR:PPP_points_per_possession (0.34); FAM:SF-APPA-050 auto_measures VAR:PPP_points_per_possession"], "attributes": {"observed_research_question": "Superstar sequential suppression: opponent play before the star", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "A specific opponent play type on the preceding possession suppresses each star's next-possession PPP relative to that star's baseline.", "observed_result": "PUTBACK is top suppressor for 6+ stars (e.g. D. Mitchell 1.178 to 0.884, d=-0.294, n_after=95; B. Beal d=-0.345 n=32; C. Holmgren d=-0.222 n=52). Other tops: TRANSITION (A. Davis -0.058), POST_UP (N. Jokic -0.075), PULL_ [cut; read_family for the full text]", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No multiplicity correction; n_after is 32-95 for several PUTBACK cells vs thousands of baseline possessions.", "observed_sample_and_power": "30 stars; min n_after=30", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:DRIFT_NONSTATIONARITY"}]}, {"id": "FAM:SF-APPM-022", "label": "Study family SF-APPM-022: Superstar suppression profiles (incl. Q5c sequential triggering)", "score": 0.288, "reached_via": ["FAM:SF-APPA-050 auto_related_family (repeated_by_later_family) FAM:SF-APPM-022", "FAM:SF-APPA-050 auto_related_family (repeat_of_earlier_family) FAM:SF-APPM-022"], "attributes": {"observed_research_question": "Superstar suppression profiles (incl. Q5c sequential triggering)", "auto_outcome_status": "inconclusive", "observed_hypothesis": "Specific opposing lineups, defenders, play types and preceding opponent play types suppress star efficiency.", "observed_result": "Q5c verdict 'rank-1 suppressor varies meaningfully across players'; e.g. Jokic after opp POST_UP 1.1271 (-0.0675, SE +/-0.0500, n=480); Curry forced POST_UP -0.209.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "Rank-1 deltas mostly within 1-2 SE with no multiple-comparison control; OTHER artifact flagged in doc.", "observed_sample_and_power": "SE per cell reported", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "inconclusive", "observed_failure_type": "E_unclear", "observed_notes": "NOT_RECORDED", "auto_confidence": "medium (0.65)"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPA-050"}]}, {"id": "FAM:SF-APPM-011", "label": "Study family SF-APPM-011: Net-swing play-type scoring prototype", "score": 0.273, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPM-011 (0.22)", "request matches VAR:PPP_points_per_possession (0.34); FAM:SF-APPM-011 auto_measures VAR:PPP_points_per_possession"], "attributes": {"observed_research_question": "Net-swing play-type scoring prototype", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Scoring PTs by own PPP minus opponent next-possession PPP changes recommendations.", "observed_result": "Top recommendation changes in 40/104 = 38% units; DRIVE median net swing -0.27 (negative 88%), POST_UP -0.22 (77%).", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "Not evaluated against outcomes; uses in-series observed opp_next_PPP.", "observed_sample_and_power": "NOT_RECORDED", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "52 playoff series / 104 team-offense units; compare rank orderings own-PPP vs net-swing.", "observed_verdict": "descriptive", "observed_failure_type": "E_unclear", "observed_notes": "NOT_RECORDED", "auto_confidence": "medium (0.65)"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPS-049"}, {"rel": "auto_addresses_question", "node": "RQC:RQC-005"}]}], "n_results": 4}

